// Dependabot Alerts Filter Autosave
// Saves user's filter preferences as they type (with debounce)

// Debounce function to limit how often the save function is called
function debounce<T extends (...args: Parameters<T>) => void>(func: T, wait: number): T {
  let timeout: ReturnType<typeof setTimeout> | undefined
  return function executedFunction(this: ThisParameterType<T>, ...args: Parameters<T>) {
    const later = () => {
      clearTimeout(timeout)
      func.apply(this, args)
    }
    clearTimeout(timeout)
    timeout = setTimeout(later, wait)
  } as T
}

// Function to save the current filter view
async function saveFilterView(query: string, saveUrl: string, csrfToken: string): Promise<void> {
  // Default queries from security_center/dependabot_alerts_query.rb
  const defaultQueries = [
    'is:open', // Default when feature flag is disabled
    'is:open severity:critical,high has:patch epss_percentage:>=0.01', // Default when feature flag is enabled
  ]

  // Don't save if the query is empty or matches one of the defaults
  if (!query || query.trim() === '' || defaultQueries.includes(query.trim())) {
    return
  }

  if (!csrfToken) {
    return
  }

  // Send POST request with form data (not JSON) for proper CSRF protection
  const formData = new URLSearchParams()
  formData.append('query', query.trim())
  // eslint-disable-next-line github/authenticity-token
  formData.append('authenticity_token', csrfToken)

  try {
    const response = await fetch(saveUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        Accept: 'application/json',
      },
      body: formData.toString(),
    })

    if (!response.ok) {
      throw new Error('Failed to save filter view')
    }

    await response.json()
  } catch {
    // Silently fail - the autosave is a best-effort feature
    // and shouldn't disrupt the user experience with errors
  }
}

// Initialize autosave functionality
function initializeAutoSave(): void {
  // Find the wrapper div that has the save path
  const wrapper = document.querySelector<HTMLElement>(
    '.dependabot-alerts-filter-autocomplete-dropdown-wrapper[data-save-view-path]',
  )

  if (!wrapper) {
    // Feature not enabled or no save path provided
    return
  }

  const saveUrl = wrapper.getAttribute('data-save-view-path')
  if (!saveUrl) {
    return
  }

  // Find the CSRF token from the hidden input
  const csrfInput = wrapper.querySelector<HTMLInputElement>('.js-dependabot-autosave-csrf')
  const csrfToken = csrfInput ? csrfInput.value : null

  if (!csrfToken) {
    return
  }

  // Find the filter input element
  const filterInput = document.querySelector<HTMLInputElement>('dependabot-alerts-filter input[name="q"]')

  if (!filterInput) {
    return
  }

  // Create debounced version of save function (2 second delay)
  const debouncedSave = debounce((query: string) => saveFilterView(query, saveUrl, csrfToken), 2000)

  // Listen for input changes
  filterInput.addEventListener('input', function (e) {
    const query = (e.target as HTMLInputElement).value
    debouncedSave(query)
  })

  // console.log('Dependabot alerts filter auto-save initialized');
}

// Initialize when DOM is ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initializeAutoSave)
} else {
  initializeAutoSave()
}
